// security_headers.rs — browser security headers on every tond-server response
//
//   Content-Security-Policy    default-src 'self', frame-ancestors 'none', …
//                              The SPA's index.html boots with one inline
//                              <script> generated by SvelteKit; its SHA-256 hash
//                              is computed from the built file at startup so no
//                              'unsafe-inline' is needed for scripts. Styles
//                              allow 'unsafe-inline' (Svelte style attributes,
//                              xterm.js); images allow data: (2FA QR code).
//                              Forms may post to github.com (GitHub App
//                              manifest flow); database logos come from
//                              cdn.jsdelivr.net (devicon).
//   Strict-Transport-Security  only when tond-proxy forwarded the request from
//                              its TLS listener (X-Forwarded-Proto: https on a
//                              loopback peer). No includeSubDomains: apps on
//                              subdomains may legitimately be plain HTTP.
//   X-Content-Type-Options     nosniff
//   Referrer-Policy            same-origin (keeps the setup token in the URL
//                              from leaking to other sites)
//   X-Frame-Options            DENY (older browsers without frame-ancestors)

use std::net::SocketAddr;
use std::path::Path;
use std::sync::OnceLock;

use axum::{
    extract::{ConnectInfo, Request},
    http::{HeaderMap, HeaderName, HeaderValue, header},
    middleware::Next,
    response::Response,
};
use base64::Engine;
use sha2::{Digest, Sha256};

use crate::auth::LocalSocket;

/// `script-src` sources, fixed at startup from the dashboard's index.html.
static SCRIPT_SRC: OnceLock<String> = OnceLock::new();

/// Compute the CSP script hashes from `<dashboard_dir>/index.html`. Call once at
/// startup; without it (API-only mode) scripts are limited to 'self'.
pub fn init_from_dashboard(dashboard_dir: &Path) {
    let html = std::fs::read_to_string(dashboard_dir.join("index.html")).unwrap_or_default();
    let _ = SCRIPT_SRC.set(script_src_for(&html));
}

/// `'self'` plus a `'sha256-…'` source for every inline script in `html`.
pub fn script_src_for(html: &str) -> String {
    let mut sources = vec!["'self'".to_string()];
    for body in inline_scripts(html) {
        let digest = Sha256::digest(body.as_bytes());
        sources.push(format!(
            "'sha256-{}'",
            base64::engine::general_purpose::STANDARD.encode(digest)
        ));
    }
    sources.join(" ")
}

/// Bodies of `<script>` elements without a `src` attribute.
fn inline_scripts(html: &str) -> Vec<&str> {
    let mut scripts = Vec::new();
    let mut rest = html;
    while let Some(start) = rest.find("<script") {
        let after = &rest[start + "<script".len()..];
        let Some(tag_end) = after.find('>') else {
            break;
        };
        let attrs = &after[..tag_end];
        let content = &after[tag_end + 1..];
        let Some(close) = content.find("</script>") else {
            break;
        };
        if !attrs.to_ascii_lowercase().contains("src=") {
            scripts.push(&content[..close]);
        }
        rest = &content[close + "</script>".len()..];
    }
    scripts
}

/// Host header value if it is a plain `host[:port]` (safe to embed in the CSP).
fn safe_host(headers: &HeaderMap) -> Option<&str> {
    let host = headers.get(header::HOST)?.to_str().ok()?;
    let valid = !host.is_empty()
        && host.len() <= 255
        && host
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b':' | b'[' | b']'));
    valid.then_some(host)
}

/// Build the Content-Security-Policy for a response to a request with `headers`.
pub fn content_security_policy(headers: &HeaderMap) -> String {
    let script_src = SCRIPT_SRC.get().map(String::as_str).unwrap_or("'self'");
    // 'self' covers same-origin ws(s): in current browsers; the explicit host
    // keeps the terminal and log streams working in older ones.
    let connect_src = match safe_host(headers) {
        Some(host) => format!("'self' wss://{host} ws://{host}"),
        None => "'self'".to_string(),
    };
    format!(
        "default-src 'self'; script-src {script_src}; style-src 'self' 'unsafe-inline'; \
         img-src 'self' data: blob: https://cdn.jsdelivr.net; font-src 'self' data:; connect-src {connect_src}; \
         worker-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self' https://github.com; \
         frame-ancestors 'none'"
    )
}

/// Whether tond-proxy received this request over TLS.
fn forwarded_over_https(req: &Request) -> bool {
    if req.extensions().get::<LocalSocket>().is_some() {
        return false;
    }
    let from_loopback = req
        .extensions()
        .get::<ConnectInfo<SocketAddr>>()
        .is_some_and(|ConnectInfo(addr)| addr.ip().is_loopback());
    from_loopback
        && req
            .headers()
            .get("x-forwarded-proto")
            .and_then(|v| v.to_str().ok())
            .is_some_and(|v| v.trim().eq_ignore_ascii_case("https"))
}

fn set_if_absent(headers: &mut HeaderMap, name: HeaderName, value: &str) {
    if !headers.contains_key(&name)
        && let Ok(value) = HeaderValue::from_str(value)
    {
        headers.insert(name, value);
    }
}

/// Axum middleware adding the security headers (see module docs).
pub async fn add_security_headers(req: Request, next: Next) -> Response {
    let https = forwarded_over_https(&req);
    let csp = content_security_policy(req.headers());

    let mut response = next.run(req).await;
    let headers = response.headers_mut();
    set_if_absent(headers, header::CONTENT_SECURITY_POLICY, &csp);
    set_if_absent(headers, header::X_CONTENT_TYPE_OPTIONS, "nosniff");
    set_if_absent(headers, header::REFERRER_POLICY, "same-origin");
    set_if_absent(headers, header::X_FRAME_OPTIONS, "DENY");
    if https {
        set_if_absent(
            headers,
            header::STRICT_TRANSPORT_SECURITY,
            "max-age=31536000",
        );
    }
    response
}

#[cfg(test)]
mod tests {
    use axum::{Router, body::Body, http::Request as HttpRequest, routing::get};
    use tower::ServiceExt;

    use super::*;

    #[test]
    fn script_src_hashes_inline_scripts_only() {
        let html = r#"<head><script src="/a.js"></script></head>
<body><div><script>
    console.log("boot");
</script></div></body>"#;
        let src = script_src_for(html);
        let expected = base64::engine::general_purpose::STANDARD
            .encode(Sha256::digest("\n    console.log(\"boot\");\n".as_bytes()));
        assert_eq!(src, format!("'self' 'sha256-{expected}'"));
        assert_eq!(script_src_for("<p>no scripts</p>"), "'self'");
    }

    #[test]
    fn csp_forbids_framing_and_embeds_only_a_safe_host() {
        let mut headers = HeaderMap::new();
        headers.insert(header::HOST, HeaderValue::from_static("dash.example.com"));
        let csp = content_security_policy(&headers);
        assert!(csp.contains("frame-ancestors 'none'"));
        assert!(csp.contains("connect-src 'self' wss://dash.example.com"));
        assert!(
            csp.contains("form-action 'self' https://github.com;"),
            "the GitHub App manifest flow posts a form to github.com"
        );
        assert!(!csp.contains("script-src 'self' 'unsafe-inline'"));

        headers.insert(
            header::HOST,
            HeaderValue::from_static("evil.test; script-src *"),
        );
        let csp = content_security_policy(&headers);
        assert!(
            csp.contains("connect-src 'self';"),
            "unsafe hosts are not embedded"
        );
    }

    fn app() -> Router {
        Router::new()
            .route("/", get(|| async { "ok" }))
            .layer(axum::middleware::from_fn(add_security_headers))
    }

    async fn headers_for(req: HttpRequest<Body>) -> HeaderMap {
        app()
            .oneshot(req)
            .await
            .unwrap_or_else(|err| panic!("request failed: {err}"))
            .headers()
            .clone()
    }

    fn with_peer(mut req: HttpRequest<Body>, peer: &str) -> HttpRequest<Body> {
        let addr: SocketAddr = peer.parse().unwrap_or_else(|err| panic!("{err}"));
        req.extensions_mut().insert(ConnectInfo(addr));
        req
    }

    #[tokio::test]
    async fn responses_carry_security_headers_and_hsts_only_behind_the_tls_proxy() {
        let proxied = with_peer(
            HttpRequest::get("/")
                .header("x-forwarded-proto", "https")
                .body(Body::empty())
                .unwrap_or_else(|err| panic!("{err}")),
            "127.0.0.1:5000",
        );
        let headers = headers_for(proxied).await;
        assert_eq!(headers["x-content-type-options"], "nosniff");
        assert_eq!(headers["referrer-policy"], "same-origin");
        assert!(
            headers["content-security-policy"]
                .to_str()
                .unwrap_or_default()
                .contains("frame-ancestors 'none'")
        );
        assert_eq!(headers["strict-transport-security"], "max-age=31536000");

        let direct = with_peer(
            HttpRequest::get("/")
                .body(Body::empty())
                .unwrap_or_else(|err| panic!("{err}")),
            "127.0.0.1:5000",
        );
        assert!(
            !headers_for(direct)
                .await
                .contains_key("strict-transport-security")
        );

        // A remote peer can't claim HTTPS by sending the header itself.
        let spoofed = with_peer(
            HttpRequest::get("/")
                .header("x-forwarded-proto", "https")
                .body(Body::empty())
                .unwrap_or_else(|err| panic!("{err}")),
            "198.51.100.1:5000",
        );
        assert!(
            !headers_for(spoofed)
                .await
                .contains_key("strict-transport-security")
        );
    }
}
